package cn.academy.port.hook;
import java.io.File;import java.net.*;import java.nio.file.Path;import java.util.*;
/** Cold linking against real cached APIs; this is not game bootstrap or a native runtime pass. */
public final class HookServerLinkTest {
    private static final class ServerLoader extends URLClassLoader {int clients;ServerLoader(URL[] urls){super(urls,ClassLoader.getPlatformClassLoader());}@Override protected Class<?> loadClass(String name,boolean resolve)throws ClassNotFoundException{if(name.startsWith("net.minecraft.client.")||name.startsWith("net.neoforged.neoforge.client.")||name.startsWith("cn.academy.port.client.")){clients++;throw new ClassNotFoundException("server denies "+name);}return super.loadClass(name,resolve);}}
    public static void main(String[] args)throws Exception{var urls=new ArrayList<URL>();for(String p:System.getProperty("java.class.path").split(java.util.regex.Pattern.quote(File.pathSeparator)))urls.add(Path.of(p).toUri().toURL());int count=0;try(var loader=new ServerLoader(urls.toArray(URL[]::new))){for(String name:List.of("cn.academy.port.hook.ClassicHookRules","cn.academy.port.hook.ClassicHooks","cn.academy.port.hook.MagHookItem","cn.academy.port.hook.MagHookEntity","cn.academy.port.clientless.ClassicLateTrig","cn.academy.port.gametest.AcademyHookRuntimeTests")){var queue=new ArrayDeque<Class<?>>();queue.add(Class.forName(name,false,loader));while(!queue.isEmpty()){var c=queue.remove();c.getDeclaredConstructors();c.getDeclaredFields();c.getDeclaredMethods();queue.addAll(List.of(c.getDeclaredClasses()));count++;}}if(loader.clients!=0)throw new AssertionError("Common Hook code requested client namespaces");}System.out.println("PASS "+count+" Hook/common fixture classes cold linked with all client namespaces denied; no bootstrap");}
}
